import java.io.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ');

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long value = 0;
            while (c > ' ') {
                value = value * 10 + c - '0';
                c = read();
            }
            return value * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Transform {
        long c, d;

        Transform(long c, long d) {
            this.c = c;
            this.d = d;
        }
    }

    // Returns g(f(x)).
    static Transform compose(Transform g, Transform f) {
        return new Transform(
                Math.max(g.c, f.c + g.d),
                f.d + g.d
        );
    }

    static long rank(boolean[] available, int n, long m) {
        Transform block = new Transform(0, 0);

        for (int pos = 1; pos <= 2 * n; pos++) {
            boolean canClose = available[(pos - 1) % n];
            Transform operation;

            if ((pos & 1) == 0) {
                operation = canClose
                        ? new Transform(0, 0)
                        : new Transform(1, 1);
            } else {
                operation = canClose
                        ? new Transform(0, -1)
                        : new Transform(0, 0);
            }

            block = compose(operation, block);
        }

        long repetitions = m / 2;
        Transform result = new Transform(0, 0);
        Transform power = block;

        while (repetitions > 0) {
            if ((repetitions & 1) != 0) {
                result = compose(power, result);
            }
            power = compose(power, power);
            repetitions >>= 1;
        }

        long slack = Math.max(result.c, result.d);
        long totalLength = (long) n * m;
        return totalLength / 2 - slack;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int n = fs.nextInt();
        long m = fs.nextLong();

        int[] a = new int[n];
        int[] b = new int[n];

        long answer = 0;
        for (int i = 0; i < n; i++) {
            a[i] = fs.nextInt();
            answer += (long) a[i] * m;
        }

        for (int i = 0; i < n; i++) {
            b[i] = fs.nextInt();
        }

        boolean[] available = new boolean[n];
        long previousRank = 0;

        for (int cost = -9; cost <= 9; cost++) {
            boolean changed = false;

            for (int i = 0; i < n; i++) {
                if (b[i] - a[i] == cost) {
                    available[i] = true;
                    changed = true;
                }
            }

            if (changed) {
                long currentRank = rank(available, n, m);
                answer += (currentRank - previousRank) * cost;
                previousRank = currentRank;
            }
        }

        System.out.println(answer);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    private static final int OFFSET = 9;
    private static final int VALUES = 19;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int n = fs.nextInt();
        long m = fs.nextLong();

        int[] a = new int[n];
        int[] b = new int[n];
        int[] delta = new int[n];

        for (int i = 0; i < n; i++) {
            a[i] = fs.nextInt();
        }

        long sumB = 0;
        for (int i = 0; i < n; i++) {
            b[i] = fs.nextInt();
            sumB += b[i];
            delta[i] = a[i] - b[i];
        }

        long length = (long) n * m;
        long pairsToProcess = length / 2 - 1;

        long answer = sumB * m + delta[0];

        if (pairsToProcess == 0) {
            System.out.println(answer);
            return;
        }

        int period = n / gcd(n, 2);
        int[][] cycle = new int[period][2];
        long[] arrivals = new long[VALUES];

        for (int i = 0; i < period; i++) {
            int first = (1 + 2 * i) % n;
            int second = (2 + 2 * i) % n;

            cycle[i][0] = delta[first] + OFFSET;
            cycle[i][1] = delta[second] + OFFSET;

            arrivals[cycle[i][0]]++;
            arrivals[cycle[i][1]]++;
        }

        long[] target = new long[VALUES];
        long cumulative = 0;
        for (int value = 0; value < VALUES; value++) {
            long needed = period - cumulative;
            if (needed <= 0) break;

            target[value] = Math.min(arrivals[value], needed);
            cumulative += target[value];
        }

        long targetCost = 0;
        for (int i = 0; i < VALUES; i++) {
            targetCost += target[i] * (i - OFFSET);
        }

        long fullCycles = pairsToProcess / period;
        int remainder = (int) (pairsToProcess % period);
        long[] available = new long[VALUES];

        while (fullCycles > 0) {
            long[] selected = new long[VALUES];
            long cycleCost = processCycle(cycle, available, selected);
            answer += cycleCost;
            fullCycles--;

            if (Arrays.equals(selected, target)) {
                answer += fullCycles * targetCost;
                fullCycles = 0;
            }
        }

        for (int i = 0; i < remainder; i++) {
            available[cycle[i][0]]++;
            available[cycle[i][1]]++;

            int chosen = firstAvailable(available);
            available[chosen]--;
            answer += chosen - OFFSET;
        }

        System.out.println(answer);
    }

    private static long processCycle(int[][] cycle, long[] available, long[] selected) {
        long cost = 0;

        for (int[] pair : cycle) {
            available[pair[0]]++;
            available[pair[1]]++;

            int chosen = firstAvailable(available);
            available[chosen]--;
            selected[chosen]++;
            cost += chosen - OFFSET;
        }

        return cost;
    }

    private static int firstAvailable(long[] available) {
        for (int i = 0; i < available.length; i++) {
            if (available[i] > 0) return i;
        }
        throw new IllegalStateException();
    }

    private static int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    private static final class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int pointer;
        private int length;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (pointer >= length) {
                length = in.read(buffer);
                pointer = 0;
                if (length <= 0) return -1;
            }
            return buffer[pointer++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ');

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long value = 0;
            while (c > ' ') {
                value = value * 10 + c - '0';
                c = read();
            }
            return value * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
}

