public class Main {
    private static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int pointer = 0, length = 0;

        private int read() throws IOException {
            if (pointer >= length) {
                length = in.read(buffer);
                pointer = 0;
                if (length <= 0) return -1;
            }
            return buffer[pointer++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value * sign;
        }
    }

    private static long rank(int[] weights, int n, long m, int threshold) {
        int allowedResidues = 0;
        for (int weight : weights) {
            if (weight <= threshold) {
                allowedResidues++;
            }
        }

        long totalAllowed = m * allowedResidues;
        int period = (n % 2 == 0) ? n / 2 : n;
        long pairCount = (long) n * m / 2;
        long cycles = pairCount / period;

        long d = 0;
        long minimumWithinCycle = 0;

        for (int t = 0; t < period; t++) {
            minimumWithinCycle = Math.min(minimumWithinCycle, d);

            int evenResidue = (2 * t) % n;
            int oddResidue = (2 * t + 1) % n;

            int evenAllowed = weights[evenResidue] <= threshold ? 1 : 0;
            int oddAllowed = weights[oddResidue] <= threshold ? 1 : 0;

            minimumWithinCycle = Math.min(minimumWithinCycle, d - evenAllowed);
            d += 1L - evenAllowed - oddAllowed;
        }

        long cycleDrift = d;
        long minimum = minimumWithinCycle;

        if (cycleDrift < 0) {
            minimum += (cycles - 1) * cycleDrift;
        }

        minimum = Math.min(minimum, cycles * cycleDrift);
        return totalAllowed + minimum;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int n = fs.nextInt();
        long m = fs.nextInt();

        int[] a = new int[n];
        int[] weights = new int[n];

        long answer = 0;
        for (int i = 0; i < n; i++) {
            a[i] = fs.nextInt();
            answer += m * a[i];
        }

        for (int i = 0; i < n; i++) {
            int b = fs.nextInt();
            weights[i] = b - a[i];
        }

        long previousRank = 0;
        for (int weight = -9; weight <= 9; weight++) {
            long currentRank = rank(weights, n, m, weight);
            answer += (currentRank - previousRank) * weight;
            previousRank = currentRank;
        }

        System.out.println(answer);
    }
}

