public class Main {
    private static final int OFFSET = 9;
    private static final int VALUES = 19;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int n = fs.nextInt();
        long m = fs.nextLong();

        int[] a = new int[n];
        int[] b = new int[n];
        int[] delta = new int[n];

        long sumB = 0;
        for (int i = 0; i < n; i++) {
            a[i] = fs.nextInt();
        }
        for (int i = 0; i < n; i++) {
            b[i] = fs.nextInt();
            sumB += b[i];
            delta[i] = a[i] - b[i];
        }

        long length = (long) n * m;
        long choices = length / 2;
        long answer = sumB * m + delta[0];

        if (choices == 1) {
            System.out.println(answer);
            return;
        }

        int period = (n % 2 == 0) ? n / 2 : n;
        long pairOperations = choices - 1;
        long fullCycles = pairOperations / period;
        int remainder = (int) (pairOperations % period);

        long[] inventory = new long[VALUES];
        long[] insertedPerCycle = new long[VALUES];

        for (int t = 0; t < period; t++) {
            int p1 = (1 + 2 * t) % n;
            int p2 = (2 + 2 * t) % n;
            insertedPerCycle[delta[p1] + OFFSET]++;
            insertedPerCycle[delta[p2] + OFFSET]++;
        }

        int cutoff = 0;
        long below = 0;
        while (cutoff < VALUES) {
            if (below + insertedPerCycle[cutoff] >= period) {
                break;
            }
            below += insertedPerCycle[cutoff++];
        }

        long[] targetExtracted = new long[VALUES];
        long targetCycleCost = 0;
        long needed = period;

        for (int v = 0; v < cutoff; v++) {
            targetExtracted[v] = insertedPerCycle[v];
            needed -= targetExtracted[v];
            targetCycleCost += targetExtracted[v] * (v - OFFSET);
        }
        targetExtracted[cutoff] = needed;
        targetCycleCost += needed * (cutoff - OFFSET);

        while (fullCycles > 0) {
            long[] extracted = new long[VALUES];
            long cycleCost = 0;

            for (int t = 0; t < period; t++) {
                int p1 = (1 + 2 * t) % n;
                int p2 = (2 + 2 * t) % n;

                inventory[delta[p1] + OFFSET]++;
                inventory[delta[p2] + OFFSET]++;

                int v = 0;
                while (inventory[v] == 0) {
                    v++;
                }
                inventory[v]--;
                extracted[v]++;
                cycleCost += v - OFFSET;
            }

            answer += cycleCost;
            fullCycles--;

            if (Arrays.equals(extracted, targetExtracted)) {
                answer += targetCycleCost * fullCycles;

                for (int v = 0; v < VALUES; v++) {
                    inventory[v] +=
                            (insertedPerCycle[v] - targetExtracted[v]) * fullCycles;
                }
                fullCycles = 0;
            }
        }

        for (int t = 0; t < remainder; t++) {
            int p1 = (1 + 2 * t) % n;
            int p2 = (2 + 2 * t) % n;

            inventory[delta[p1] + OFFSET]++;
            inventory[delta[p2] + OFFSET]++;

            int v = 0;
            while (inventory[v] == 0) {
                v++;
            }
            inventory[v]--;
            answer += v - OFFSET;
        }

        System.out.println(answer);
    }

