import java.io.*;
import java.util.*;

public class Main {
    private static final int OFFSET = 9;
    private static final int LEVELS = 19;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int n = fs.nextInt();
        long m = fs.nextLong();

        int[] a = new int[n];
        int[] b = new int[n];

        long answer = 0;
        for (int i = 0; i < n; i++) {
            a[i] = fs.nextInt();
            answer += m * a[i];
        }
        for (int i = 0; i < n; i++) {
            b[i] = fs.nextInt();
        }

        int[] costLevel = new int[n];
        for (int i = 0; i < n; i++) {
            costLevel[i] = b[i] - a[i] + OFFSET;
        }

        long totalLength = (long) n * m;
        long closes = totalLength / 2;

        // The last bracket is forced to be closed.
        answer += b[n - 1] - a[n - 1];

        long remaining = closes - 1;
        if (remaining == 0) {
            System.out.println(answer);
            return;
        }

        int period = n / gcd(n, 2);
        int[][] additions = new int[period][2];
        long[] additionsPerPeriod = new long[LEVELS];

        for (int phase = 0; phase < period; phase++) {
            long s = phase + 1L;
            int r1 = floorMod(-2L * s - 1, n);
            int r2 = floorMod(-2L * s, n);

            additions[phase][0] = costLevel[r1];
            additions[phase][1] = costLevel[r2];
            additionsPerPeriod[costLevel[r1]]++;
            additionsPerPeriod[costLevel[r2]]++;
        }

        int threshold = 0;
        long cumulative = 0;
        while (threshold < LEVELS) {
            cumulative += additionsPerPeriod[threshold];
            if (cumulative >= period) {
                break;
            }
            threshold++;
        }

        long[] count = new long[LEVELS];
        boolean jumped = false;

        while (remaining >= period && !jumped) {
            long[] lowerBefore = Arrays.copyOf(count, threshold);
            long[] removed = new long[LEVELS];
            long periodCost = 0;
            boolean removedAboveThreshold = false;

            for (int phase = 0; phase < period; phase++) {
                count[additions[phase][0]]++;
                count[additions[phase][1]]++;

                int chosen = firstNonEmpty(count);
                count[chosen]--;
                removed[chosen]++;
                periodCost += chosen - OFFSET;

                if (chosen > threshold) {
                    removedAboveThreshold = true;
                }
            }

            answer += periodCost;
            remaining -= period;

            boolean lowerUnchanged = true;
            for (int i = 0; i < threshold; i++) {
                if (count[i] != lowerBefore[i]) {
                    lowerUnchanged = false;
                    break;
                }
            }

            if (!removedAboveThreshold && lowerUnchanged) {
                long fullPeriods = remaining / period;
                if (fullPeriods > 0) {
                    answer += fullPeriods * periodCost;

                    for (int i = 0; i < LEVELS; i++) {
                        count[i] += fullPeriods
                                * (additionsPerPeriod[i] - removed[i]);
                    }

                    remaining -= fullPeriods * period;
                }
                jumped = true;
            }
        }

        int phase = 0;
        while (remaining > 0) {
            count[additions[phase][0]]++;
            count[additions[phase][1]]++;

            int chosen = firstNonEmpty(count);
            count[chosen]--;
            answer += chosen - OFFSET;

            phase++;
            if (phase == period) {
                phase = 0;
            }
            remaining--;
        }

        System.out.println(answer);
    }

    private static int firstNonEmpty(long[] count) {
        for (int i = 0; i < count.length; i++) {
            if (count[i] > 0) {
                return i;
            }
        }
        throw new IllegalStateException();
    }

    private static int floorMod(long value, int mod) {
        long result = value % mod;
        if (result < 0) {
            result += mod;
        }
        return (int) result;
    }

    private static int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    private static final class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int pointer = 0;
        private int length = 0;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (pointer >= length) {
                length = in.read(buffer);
                pointer = 0;
                if (length <= 0) {
                    return -1;
                }
            }
            return buffer[pointer++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ');

            boolean negative = false;
            if (c == '-') {
                negative = true;
                c = read();
            }

            long value = 0;
            while (c > ' ') {
                value = value * 10 + c - '0';
                c = read();
            }
            return negative ? -value : value;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
}
